278→function AlgorithmCard({
279→  id,
280→  label,
281→  description,
282→  badge,
283→  badgeTone,
284→  selected,
285→  disabled,
286→  onSelect,
287→}: {
288→  id: string;
289→  label: string;
290→  description: string;
291→  badge: string;
292→  badgeTone: string;
293→  selected: boolean;
294→  disabled: boolean;
295→  onSelect: (v: string) => void;
296→}) {
297→  return (
298→    <div
299→      role="button"
300→      tabIndex={disabled ? -1 : 0}
301→      onClick={() => !disabled && onSelect(id)}
302→      onKeyDown={(e) => {
303→        if (!disabled && (e.key === "Enter" || e.key === " ")) {
304→          e.preventDefault();
305→          onSelect(id);
306→        }
307→      }}
308→      style={{
309→        cursor: disabled ? "not-allowed" : "pointer",
310→        borderRadius: "12px",
311→        outline: selected ? "2px solid #005bd3" : "none",
312→        opacity: disabled ? 0.5 : 1,
313→        flex: "1 1 0",
314→        minWidth: "160px",
315→      }}
316→    >
317→      <Card>
318→        <BlockStack gap="200">
319→          <InlineStack gap="200" blockAlign="center">
320→            <Text as="p" variant="bodyMd">{label}</Text>
321→            {selected && <Badge tone="info">Active</Badge>}
322→          </InlineStack>
323→          <Text as="p" variant="bodyMd" tone="subdued">{description}</Text>
324→          <Badge tone={badgeTone as "success" | "enabled" | "warning" | "critical" | "info"}>{badge}</Badge>
325→        </BlockStack>
326→      </Card>
327→    </div>
328→  );
329→}
330→
331→function FitCard({
332→  id,
333→  label,
334→  description,
335→  selected,
336→  onSelect,
337→}: {
338→  id: string;
339→  label: string;
340→  description: string;
341→  selected: boolean;
342→  onSelect: (v: string) => void;
343→}) {
344→  return (
345→    <div
346→      role="button"
347→      tabIndex={0}
348→      onClick={() => onSelect(id)}
349→      onKeyDown={(e) => {
350→        if (e.key === "Enter" || e.key === " ") {
351→          e.preventDefault();
352→          onSelect(id);
353→        }
354→      }}
355→      style={{
356→        cursor: "pointer",
357→        borderRadius: "12px",
358→        outline: selected ? "2px solid #005bd3" : "none",
359→        flex: "1 1 0",
360→        minWidth: "120px",
361→      }}
362→    >
363→      <Card>
364→        <BlockStack gap="200">
365→          <InlineStack gap="200" blockAlign="center">
366→            <Text as="p" variant="bodyMd">{label}</Text>
367→            {selected && <Badge tone="info">Selected</Badge>}
368→          </InlineStack>
369→          <Text as="p" variant="bodyMd" tone="subdued">{description}</Text>
370→        </BlockStack>
371→      </Card>
372→    </div>
373→  );
374→}
