377→// Main Component
378→// ---------------------------------------------------------------------------
379→
380→export default function Recommender() {
381→  const {
382→    config,
383→    bodyTypes: initialBodyTypes,
384→    fitPreference: initialFitPreference,
385→    betweenSizes: initialBetweenSizes,
386→    plan,
387→    canUseAi,
388→    canUseAdvanced,
389→    charts,
390→  } = useLoaderData<typeof loader>();
391→
392→  const fetcher = useFetcher<typeof action>();
393→  const shopify = useAppBridge();
394→  const navigate = useNavigate();
395→  const isLoading = fetcher.state !== "idle";
396→
397→  // Local state that mirrors the DB-loaded values
398→  const [enabled, setEnabled] = useState<boolean>(config.enabled);
399→  const [algorithm, setAlgorithm] = useState<string>(config.algorithm);
400→  const [bodyTypes, setBodyTypes] = useState<BodyTypeConfig[]>(initialBodyTypes);
401→  const [fitPreference, setFitPreference] = useState<string>(initialFitPreference);
402→  const [betweenSizes, setBetweenSizes] = useState<string>(initialBetweenSizes);
403→
404→  // Test recommendation inputs
405→  const [testChartId, setTestChartId] = useState<string>(charts[0]?.id ?? "");
406→  const [testHeight, setTestHeight] = useState<string>("170");
407→  const [testWeight, setTestWeight] = useState<string>("65");
408→  const [testGender, setTestGender] = useState<string>("female");
409→  const [testBodyType, setTestBodyType] = useState<string>("regular");
410→  const [testResult, setTestResult] = useState<TestResult | null>(null);
411→
412→  useEffect(() => {
413→    if (!fetcher.data) return;
414→
415→    if ("ok" in fetcher.data) {
416→      shopify.toast.show(fetcher.data.message ?? "Saved");
417→
418→      if (fetcher.data.intent === "toggle" && "enabled" in fetcher.data) {
419→        setEnabled(fetcher.data.enabled as boolean);
420→      }
421→
422→      if (fetcher.data.intent === "test-recommendation" && "testResult" in fetcher.data) {
423→        setTestResult(fetcher.data.testResult as TestResult);
424→      }
425→    } else if ("error" in fetcher.data) {
426→      shopify.toast.show(fetcher.data.error ?? "An error occurred", { isError: true });
427→    }
428→  }, [fetcher.data, shopify]);
429→
430→  const submitToggle = () => {
431→    const fd = new FormData();
432→    fd.set("intent", "toggle");
433→    fetcher.submit(fd, { method: "post" });
434→  };
435→
436→  const submitAlgorithm = (algo: string) => {
437→    setAlgorithm(algo);
438→    const fd = new FormData();
439→    fd.set("intent", "update-settings");
440→    fd.set("algorithm", algo);
441→    fetcher.submit(fd, { method: "post" });
442→  };
443→
444→  const toggleBodyType = (id: string, checked: boolean) => {
445→    const updated = bodyTypes.map((bt) => bt.id === id ? { ...bt, enabled: checked } : bt);
446→    setBodyTypes(updated);
447→    const fd = new FormData();
448→    fd.set("intent", "save-body-types");
449→    fd.set("bodyTypes", JSON.stringify(updated.map((bt) => ({ id: bt.id, enabled: bt.enabled }))));
450→    fetcher.submit(fd, { method: "post" });
451→  };
452→
453→  const submitSizingRules = () => {
454→    const fd = new FormData();
455→    fd.set("intent", "save-sizing-rules");
456→    fd.set("fitPreference", fitPreference);
457→    fd.set("betweenSizes", betweenSizes);
458→    fetcher.submit(fd, { method: "post" });
459→  };
460→
461→  const submitTestRecommendation = () => {
462→    const fd = new FormData();
463→    fd.set("intent", "test-recommendation");
464→    fd.set("chartId", testChartId);
465→    fd.set("height", testHeight);
466→    fd.set("weight", testWeight);
467→    fd.set("gender", testGender);
468→    fd.set("bodyType", testBodyType);
469→    fd.set("fitPreference", fitPreference);
470→    fetcher.submit(fd, { method: "post" });
471→  };
472→
473→  const FIT_OPTIONS = [
474→    { id: "tight", label: "Tight", description: "Fitted, closer to body — recommend smaller" },
475→    { id: "true-to-size", label: "True to Size", description: "Standard fit — no adjustment" },
476→    { id: "relaxed", label: "Relaxed", description: "Slightly loose — recommend larger" },
477→    { id: "oversized", label: "Oversized", description: "Very loose, fashion-forward — recommend up" },
478→  ];
479→
480→  const betweenSizesOptions = [
481→    { label: "Recommend smaller size", value: "smaller" },
482→    { label: "Recommend larger size", value: "larger" },
483→  ];
484→
485→  const genderOptions = [
486→    { label: "Female", value: "female" },
487→    { label: "Male", value: "male" },
488→    { label: "Unisex", value: "unisex" },
489→  ];
490→
491→  const chartOptions = charts.map((c) => ({
492→    label: `${c.name} (${c.category})`,
493→    value: c.id,
494→  }));
495→
496→  const enabledBodyTypeOptions = bodyTypes
497→    .filter((bt) => bt.enabled)
498→    .map((bt) => ({ label: bt.label, value: bt.id }));
499→
500→  // -----------------------------------------------------------------------
501→  // UPGRADE PROMPT — plan doesn't include AI
502→  // -----------------------------------------------------------------------
503→  if (!canUseAi) {
504→    return (
505→      <Page
506→        title="AI Size Recommender"
507→        backAction={{ onAction: () => navigate("/app") }}
508→      >
509→        <BlockStack gap="600">
510→          <Card>
511→            <BlockStack gap="400">
512→              <Text as="h2" variant="headingMd" fontWeight="bold">Unlock AI Size Recommendations</Text>
513→              <Text as="p" variant="bodyMd" tone="subdued">
514→                Help customers find their perfect fit using height, weight, and body type. Reduce size-related returns by up to 40%.
515→              </Text>
516→
517→              <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
518→                <Card>
519→                  <BlockStack gap="200">
520→                    <Text as="p" variant="bodyMd">Personalized sizing</Text>
521→                    <Text as="p" variant="bodyMd" tone="subdued">Customers enter their measurements and get an instant size recommendation.</Text>
522→                  </BlockStack>
523→                </Card>
524→                <Card>
525→                  <BlockStack gap="200">
526→                    <Text as="p" variant="bodyMd">No API costs</Text>
527→                    <Text as="p" variant="bodyMd" tone="subdued">All computation runs server-side. No per-request fees, ever.</Text>
528→                  </BlockStack>
529→                </Card>
530→                <Card>
531→                  <BlockStack gap="200">
532→                    <Text as="p" variant="bodyMd">Confidence scores</Text>
533→                    <Text as="p" variant="bodyMd" tone="subdued">Each recommendation shows a confidence percentage and alternatives.</Text>
534→                  </BlockStack>
535→                </Card>
536→              </InlineGrid>
537→
538→              <Banner tone="info" title="Available on Growth plan — $9.99/mo">
539→                <BlockStack gap="200">
540→                  <List type="bullet">
541→                    <List.Item>Basic AI recommender included</List.Item>
542→                    <List.Item>Analytics dashboard</List.Item>
543→                    <List.Item>Unlimited charts + Translate &amp; Adapt</List.Item>
544→                  </List>
545→                  <Button variant="primary" url="/app/pricing">
546→                    Upgrade to Growth — $9.99/mo
547→                  </Button>
548→                </BlockStack>
549→              </Banner>
550→            </BlockStack>
551→          </Card>
552→        </BlockStack>
553→      </Page>
554→    );
555→  }
556→
557→  // -----------------------------------------------------------------------
558→  // FULL PAGE — plan allows AI
559→  // -----------------------------------------------------------------------
560→  return (
561→    <Page
562→      title="AI Size Recommender"
563→      backAction={{ onAction: () => navigate("/app") }}
564→      primaryAction={
565→        <Button
566→          variant={enabled ? "secondary" : "primary"}
567→          onClick={submitToggle}
568→          loading={isLoading && fetcher.formData?.get("intent") === "toggle"}
569→        >
570→          {enabled ? "Disable Recommender" : "Enable Recommender"}
571→        </Button>
572→      }
573→    >
574→      <BlockStack gap="600">
575→
576→        {/* ================================================================ */}
577→        {/* SECTION 1 — Recommender Status                                    */}
578→        {/* ================================================================ */}
579→        <Card>
580→          <BlockStack gap="400">
581→            <Text as="h2" variant="headingMd" fontWeight="bold">Recommender Status</Text>
582→
583→            <InlineStack gap="400" blockAlign="start">
584→              <BlockStack gap="200">
585→                <InlineStack gap="200" blockAlign="center">
586→                  <Text as="p" variant="bodyMd">Status</Text>
587→                  <Badge tone={enabled ? "success" : "enabled"}>
588→                    {enabled ? "Active" : "Disabled"}
589→                  </Badge>
590→                </InlineStack>
591→                <Text as="p" variant="bodyMd" tone="subdued">
592→                  {enabled
593→                    ? 'Customers see a "Find My Size" button on product pages. The AI returns a recommended size with confidence score and alternatives.'
594→                    : 'Enable to show the "Find My Size" button on product pages. Customers enter height, weight, and body type to get personalized recommendations.'}
595→                </Text>
596→              </BlockStack>
597→              <Checkbox
598→                label="Enable AI Recommender"
599→                labelHidden
600→                checked={enabled}
601→                onChange={(checked) => {
602→                  if (checked !== enabled) submitToggle();
603→                }}
604→              />
605→            </InlineStack>
606→
607→            {enabled && (
