196→function BarChart({ data }: { data: DailyDataPoint[] }) {
197→  const max = Math.max(...data.map((d) => d.value), 1);
198→  return (
199→    <div style={{ display: "flex", alignItems: "flex-end", gap: "2px", height: "120px" }}>
200→      {data.map((d, i) => (
201→        <div
202→          key={i}
203→          style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center" }}
204→          title={`${d.label}: ${d.value} views`}
205→        >
206→          <div
207→            style={{
208→              width: "100%",
209→              background: "#005bd3",
210→              borderRadius: "2px 2px 0 0",
211→              height: `${(d.value / max) * 100}%`,
212→              minHeight: d.value > 0 ? "2px" : "0",
213→            }}
214→          />
215→        </div>
216→      ))}
217→    </div>
218→  );
219→}
