494→                          <Badge tone={parseFloat(stats.clickRate) >= 20 ? "success" : "info"}>
495→                            {`${stats.clickRate}%`}
496→                          </Badge>
497→                        </InlineStack>
498→                        <Text as="p" variant="bodyMd" tone="subdued">
499→                          {stats.totalClicks.toLocaleString()} of {stats.totalViews.toLocaleString()} chart viewers clicked inside
500→                        </Text>
501→                        <FunnelBar rate={parseFloat(stats.clickRate)} color="#005bd3" />
502→                      </BlockStack>
503→                    </Card>
504→
505→                    <Card>
506→                      <BlockStack gap="200">
507→                        <InlineStack align="space-between" blockAlign="center">
508→                          <Text as="p" variant="bodyMd">Interactions → AI Recommendations</Text>
509→                          <Badge tone={parseFloat(stats.recommendRate) >= 30 ? "success" : "info"}>
510→                            {`${stats.recommendRate}%`}
511→                          </Badge>
512→                        </InlineStack>
513→                        <Text as="p" variant="bodyMd" tone="subdued">
514→                          {stats.totalRecommendations.toLocaleString()} customers used the AI size recommender
515→                        </Text>
516→                        <FunnelBar rate={parseFloat(stats.recommendRate)} color="#2c7be5" />
517→                      </BlockStack>
518→                    </Card>
519→
520→                    <Card>
521→                      <BlockStack gap="200">
522→                        <InlineStack align="space-between" blockAlign="center">
523→                          <Text as="p" variant="bodyMd">Recommendations → Conversions</Text>
524→                          <Badge tone={parseFloat(stats.convertRate) >= 40 ? "success" : "info"}>
525→                            {`${stats.convertRate}%`}
526→                          </Badge>
527→                        </InlineStack>
528→                        <Text as="p" variant="bodyMd" tone="subdued">
529→                          {stats.totalConverts.toLocaleString()} customers added to cart after receiving a recommendation
530→                        </Text>
531→                        <FunnelBar rate={parseFloat(stats.convertRate)} color="#1a73e8" />
532→                      </BlockStack>
533→                    </Card>
534→
535→                    <Card>
536→                      <BlockStack gap="200">
537→                        <InlineStack align="space-between" blockAlign="center">
538→                          <Text as="p" variant="bodyMd">Overall: Views → Conversions</Text>
539→                          <Badge tone={parseFloat(stats.overallConvertRate) >= 5 ? "success" : "info"}>
540→                            {`${stats.overallConvertRate}%`}
541→                          </Badge>
542→                        </InlineStack>
543→                        <Text as="p" variant="bodyMd" tone="subdued">
544→                          End-to-end conversion rate — customers who viewed a chart and then added to cart
545→                        </Text>
546→                        <FunnelBar rate={parseFloat(stats.overallConvertRate) * 5} color="#16a34a" />
547→                      </BlockStack>
548→                    </Card>
549→                  </BlockStack>
550→                </BlockStack>
551→              </Card>
552→            )}
553→
554→            {/* ================================================================ */}
555→            {/* TOP CHARTS BY VIEWS                                              */}
556→            {/* ================================================================ */}
557→            <Card>
558→              <BlockStack gap="400">
559→                <Text as="h2" variant="headingMd" fontWeight="bold">Top Size Charts</Text>
560→                {topChartsWithNames.length === 0 ? (
561→                  <Text as="p" variant="bodyMd" tone="subdued">
562→                    No chart views in this period. Data appears once customers start viewing your size charts.
563→                  </Text>
564→                ) : (
565→                  <BlockStack gap="200">
566→                    {topChartsWithNames.map((chart) => (
567→                      <Card key={chart.chartId ?? chart.rank}>
568→                        <InlineStack gap="400" blockAlign="center">
569→                          <RankBadge rank={chart.rank} />
570→                          <BlockStack gap="100">
571→                            <Button
572→                              variant="plain"
573→                              url={chart.chartId ? `/app/size-charts/${chart.chartId}` : "/app/size-charts"}
574→                            >
575→                              {chart.chartName}
576→                            </Button>
577→                            <Text as="p" variant="bodyMd" tone="subdued">{chart.views.toLocaleString()} view{chart.views !== 1 ? "s" : ""}</Text>
578→                          </BlockStack>
579→                        </InlineStack>
580→                      </Card>
581→                    ))}
582→                  </BlockStack>
583→                )}
584→              </BlockStack>
585→            </Card>
586→
587→            {/* ================================================================ */}
588→            {/* INSIGHTS + UPSELL (inline)                                       */}
589→            {/* ================================================================ */}
590→            {hasData && stats !== null && (parseFloat(stats.clickRate) < 10 || parseFloat(stats.recommendRate) < 20) && (
591→              <Card>
592→                <BlockStack gap="400">
593→                  <Text as="h2" variant="headingMd" fontWeight="bold">Insights</Text>
594→                  <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
