599→                          <Text as="p" variant="bodyMd" tone="subdued">
600→                            Below 10% — try moving your widget higher on the product page.
601→                          </Text>
602→                        </BlockStack>
603→                      </Card>
604→                    )}
605→                    {parseFloat(stats.recommendRate) < 20 && (
606→                      <Card>
607→                        <BlockStack gap="200">
608→                          <Badge tone="warning">AI underused</Badge>
609→                          <Text as="p" variant="bodyMd" tone="subdued">
610→                            Fewer than 20% of interactions use the AI recommender.
611→                          </Text>
612→                        </BlockStack>
613→                      </Card>
614→                    )}
615→                  </InlineGrid>
616→                </BlockStack>
617→              </Card>
618→            )}
619→
620→            {!canViewReturnAttribution && (
621→              <Banner tone="info" title="Unlock Return Attribution">
622→                <InlineStack gap="400" blockAlign="center">
623→                  <Text as="p" variant="bodyMd">
624→                    See which charts reduce returns and calculate revenue saved. Available on Pro plan.
625→                  </Text>
626→                  <Button url="/app/pricing">Upgrade to Pro</Button>
627→                </InlineStack>
628→              </Banner>
629→            )}
630→
631→          </BlockStack>
632→        </Layout.Section>
633→      </Layout>
634→    </Page>
635→  );
636→}
